//! The packed Unicode character properties: two words per code point
//! and the side tables they name.
//!
//! Generated from the Unicode 18.0.0 character database files in
//! `support/unicode_gen/data/18.0.0` by `cargo run --release -p unicode_gen`,
//! then `cargo fmt`. Do not edit: change the generator and run it again. The
//! generator's documentation (`support/unicode_gen/src/main.rs`) says what
//! each field holds and why, and `super` reads them.

use super::ScriptId;

/// The version of Unicode the tables are generated from.
pub(super) const UNICODE_VERSION: (u8, u8, u8) = (18, 0, 0);

// The core word, read for every character.
pub(super) const BIDI_CLASS_SHIFT: u32 = 0;
pub(super) const BIDI_CLASS_MASK: u32 = 0x1F;
pub(super) const SCRIPT_SHIFT: u32 = 5;
pub(super) const SCRIPT_MASK: u32 = 0x3FF;
pub(super) const BRACKET_PAIR_SHIFT: u32 = 15;
pub(super) const BRACKET_PAIR_MASK: u32 = 0x7F;
pub(super) const OPENS_BRACKET: u32 = 1 << 22;
pub(super) const REGIONAL_INDICATOR: u32 = 1 << 23;
pub(super) const EXTENDED_PICTOGRAPHIC: u32 = 1 << 24;
pub(super) const EMOJI_PRESENTATION: u32 = 1 << 25;
pub(super) const PARAGRAPH_SEPARATOR: u32 = 1 << 26;
pub(super) const WHITE_SPACE: u32 = 1 << 27;
pub(super) const COMPLEX_CONTEXT: u32 = 1 << 28;
pub(super) const MARK: u32 = 1 << 29;
pub(super) const EMOJI: u32 = 1 << 30;

// The rare word, read per cluster or behind a gate.
pub(super) const JOIN_CAUSING: u32 = 1 << 0;
pub(super) const WIDE: u32 = 1 << 1;
pub(super) const UPRIGHT_IN_MIXED: u32 = 1 << 2;
pub(super) const CONDITIONAL_JAPANESE_STARTER: u32 = 1 << 3;
pub(super) const GLUE: u32 = 1 << 4;
#[cfg(test)]
pub(super) const EMOJI_MODIFIER_BASE: u32 = 1 << 5;
#[cfg(test)]
pub(super) const EMOJI_COMPONENT: u32 = 1 << 6;
pub(super) const DEFAULT_IGNORABLE: u32 = 1 << 7;
pub(super) const GRAPHEME_CLUSTER_BREAK_SHIFT: u32 = 8;
pub(super) const GRAPHEME_CLUSTER_BREAK_MASK: u32 = 0xF;
pub(super) const INDIC_CONJUNCT_BREAK_SHIFT: u32 = 12;
pub(super) const INDIC_CONJUNCT_BREAK_MASK: u32 = 0x3;
pub(super) const GRAPHEME_PICTOGRAPHIC: u32 = 1 << 14;
#[cfg(feature = "css")]
pub(super) const EAST_ASIAN_SPACING_SHIFT: u32 = 15;
#[cfg(feature = "css")]
pub(super) const EAST_ASIAN_SPACING_MASK: u32 = 0x7;
#[cfg(feature = "css")]
pub(super) const TEXT_SPACING_SHIFT: u32 = 18;
#[cfg(feature = "css")]
pub(super) const TEXT_SPACING_MASK: u32 = 0xF;
#[cfg(feature = "css")]
pub(super) const EMPHASIS_SHIFT: u32 = 22;
#[cfg(feature = "css")]
pub(super) const EMPHASIS_MASK: u32 = 0x7;
#[cfg(feature = "css")]
pub(super) const FIRST_LETTER_SHIFT: u32 = 25;
#[cfg(feature = "css")]
pub(super) const FIRST_LETTER_MASK: u32 = 0x3;
pub(super) const CASED: u32 = 1 << 27;
pub(super) const CASE_IGNORABLE: u32 = 1 << 28;
#[cfg(feature = "css")]
pub(super) const LETTER_OR_NUMBER: u32 = 1 << 29;

// The line byte, read by the line segmenter for every character.
pub(super) const LINE_CLASS_SHIFT: u32 = 0;
pub(super) const LINE_CLASS_MASK: u32 = 0x3F;
pub(super) const LINE_EAST_ASIAN: u32 = 1 << 6;
pub(super) const LINE_UNASSIGNED_PICTOGRAPHIC: u32 = 1 << 7;

// The word byte, read by the word segmenter for every character.
pub(super) const WORD_CLASS_SHIFT: u32 = 0;
pub(super) const WORD_CLASS_MASK: u32 = 0x1F;
pub(super) const WORD_PICTOGRAPHIC: u32 = 1 << 5;
pub(super) const WORD_RUN_SHIFT: u32 = 6;
pub(super) const WORD_RUN_MASK: u32 = 0x3;
pub(super) const WORD_RUN_SOUTHEAST_ASIAN: u32 = 1;
pub(super) const WORD_RUN_CHINESE_JAPANESE: u32 = 2;

/// The number of script values. A script field below this is a script; at
