/// The rare word of `ch`, from packtab's [2^8,2^7,2^1] layout: three reads.
#[cfg(not(feature = "css"))]
#[allow(
    clippy::unnecessary_cast,
    reason = "packtab casts every index to usize, whatever its type"
)]
#[inline]
pub(super) fn rare_word(ch: char) -> u32 {
    let u = ch as usize;
    if u < 1114110usize {
        (at(
            &RARE_U32,
            (((at(
                &RARE_U8,
                4352usize
                    + ((((at(&RARE_U8, ((((u) >> 1) >> 7) as usize) as usize)) as usize) << 7)
                        as usize
                        + (((u) >> 1) & 127) as usize) as usize,
            )) as usize)
                << 1) as usize
                + ((u) & 1) as usize,
        )) as u32
    } else {
        0
    }
}

