/// The word_break word of `ch`, from packtab's [2^8,2^6,2^2] layout: three reads.
#[allow(
    clippy::unnecessary_cast,
    reason = "packtab casts every index to usize, whatever its type"
)]
#[inline]
pub(super) fn word_break_word(ch: char) -> u8 {
    let u = ch as usize;
    if u < 918000usize {
        (at(
            &WORD_BREAK_U8,
            13442usize
                + ((((at(
                    &WORD_BREAK_U8,
                    3586usize
                        + ((((at(&WORD_BREAK_U8, ((((u) >> 2) >> 6) as usize) as usize)) as usize)
                            << 6) as usize
                            + (((u) >> 2) & 63) as usize) as usize,
                )) as usize)
                    << 2) as usize
                    + ((u) & 3) as usize) as usize,
        )) as u8
    } else {
        0
    }
}

/// `table[i]`, or zero past the end of `table`.
///
/// No index a lookup computes is past the end: the sweep test visits every
/// character. The zero is there so that no input can reach a panic.
#[inline(always)]
fn at<T: Copy + Default>(table: &[T], i: usize) -> T {
    match table.get(i) {
        Some(value) => *value,
        None => T::default(),
    }
}
